```python
# Servidor simple con Flask
from flask import Flask, jsonify, request
app = Flask(__name__)

@app.route('/saludo', methods=['GET'])
def saludo():
    nombre = request.args.get('nombre', 'Mundo')
    return jsonify(mensaje=f'Hola, {nombre}!')

if __name__ == '__main__':
    app.run(port=5000)
```
```bash
# Cliente con curl
curl "http://localhost:5000/saludo?nombre=Ana"
# Respuesta: {"mensaje":"Hola, Ana!"}
```
